const chainSteps=ch=>{const st=[];for(let i=0;i<ch.length;i+=2)st.push({L:ch[i],R:ch[i+1]});return st;};
const chainMembers=st=>[st[0].L[0],...st.map(s=>s.R[0])];
const reag=s=>s.L.length>1?s.L.slice(1).map(x=>C(x)).join(', '):'t°';
